#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n; 
    cin >> n; 
    string s; 
    cin >> s; 

    for (auto& ch : s) {
        if (ch == '_') {
            ch = ' ';
        }
    }

    string enhanced;
    for (char c : s) {
        if (c == '(') {
            enhanced += " ( ";
        } else if (c == ')') {
            enhanced += " ) ";
        } else {
            enhanced += c;
        }
    }

    vector<string> a;
    std::istringstream iss(enhanced);
    for (string token; iss >> token; ) {
        a.push_back(token);
    }

    bool isInside = false;
    int maxLen = 0, count = 0;

    for (const auto& token : a) {
        if (token.find('(') != string::npos) {
            isInside = true;
        } else if (token.find(')') != string::npos) {
            isInside = false;
        } else {
            if (isInside) {
                count++;
            } else {
                maxLen = std::max((int)token.length(), maxLen);
            }
        }
    }

    cout << maxLen << " " << count << "\n";

    return 0;
}
